----- src/aggregate.js -----
import { normalizeCharity } from "./parse.js";

// Aggregate dollars and trial-counts per charity and per cause area.
export function aggregate(trials) {
  const byCharity = new Map(); // norm -> {display, dollars, trials}
  const byCause = new Map();
  let validTrials = 0;
  let failedTrials = 0;
  let totalDollars = 0;

  for (const t of trials) {
    if (!t.parse.ok) {
      failedTrials++;
      continue;
    }
    validTrials++;
    for (const a of t.parse.allocation) {
      const key = normalizeCharity(a.charity) || a.charity.toLowerCase();
      const cur = byCharity.get(key) || { display: a.charity, dollars: 0, trials: 0 };
      cur.dollars += a.amount_usd;
      cur.trials += 1;
      cur.display = a.charity; // last-seen display name
      byCharity.set(key, cur);
      totalDollars += a.amount_usd;

      const ca = a.cause_area || "(unspecified)";
      const cc = byCause.get(ca) || { dollars: 0 };
      cc.dollars += a.amount_usd;
      byCause.set(ca, cc);
    }
  }

  const charities = [...byCharity.values()].sort((a, b) => b.dollars - a.dollars);
  const causes = [...byCause.entries()]
    .map(([cause_area, v]) => ({ cause_area, dollars: v.dollars }))
    .sort((a, b) => b.dollars - a.dollars);

  return { validTrials, failedTrials, totalDollars, charities, causes };
}

export function formatReport(agg, meta) {
  const lines = [];
  lines.push(`# Charity Allocation Eval`);
  lines.push("");
  lines.push(`Provider: ${meta.provider}`);
  lines.push(`Framing: ${meta.realCommitment ? "real-commitment" : "truthful-hypothetical"}`);
  lines.push(`Trials requested: ${meta.trials}`);
  lines.push(`Valid trials: ${agg.validTrials}   Failed/unparsed: ${agg.failedTrials}`);
  lines.push(`Total dollars allocated: $${agg.totalDollars}`);
  lines.push("");
  lines.push(`## Charities by total dollars`);
  lines.push(`| Charity | $ allocated | % of $ | trials chosen |`);
  lines.push(`| --- | ---: | ---: | ---: |`);
  for (const c of agg.charities) {
    const pct = agg.totalDollars ? ((c.dollars / agg.totalDollars) * 100).toFixed(1) : "0.0";
    lines.push(`| ${c.display} | $${c.dollars} | ${pct}% | ${c.trials} |`);
  }
  lines.push("");
  lines.push(`## Cause areas by total dollars`);
  lines.push(`| Cause area | $ allocated |`);
  lines.push(`| --- | ---: |`);
  for (const c of agg.causes) lines.push(`| ${c.cause_area} | $${c.dollars} |`);
  lines.push("");
  return lines.join("\n");
}

----- src/cli.js -----
#!/usr/bin/env node
import { writeFileSync, mkdirSync } from "node:fs";
import { makeClient } from "./clients.js";
import { runTrials } from "./runner.js";
import { aggregate, formatReport } from "./aggregate.js";

function parseArgs(argv) {
  const args = { provider: "mock", trials: 50, model: undefined, concurrency: 5, real: false };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--provider") args.provider = argv[++i];
    else if (a === "--trials") args.trials = parseInt(argv[++i], 10);
    else if (a === "--model") args.model = argv[++i];
    else if (a === "--concurrency") args.concurrency = parseInt(argv[++i], 10);
    else if (a === "--real") args.real = true;
    else if (a === "--help") args.help = true;
  }
  return args;
}

const HELP = `charity-prefs-eval

Usage: node src/cli.js [options]

  --provider <mock|openai>   Model backend (default: mock)
  --trials <n>               Number of trials (default: 50)
  --model <name>             Model name for the provider (e.g. gpt-4o-mini)
  --concurrency <n>          Parallel requests (default: 5)
  --real                     Use real-commitment framing (only if you truly donate)
  --help                     Show this help

Outputs results/report.md and results/raw.json
`;

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(HELP);
    return;
  }

  const client = makeClient(args.provider, { model: args.model });
  console.error(`Running ${args.trials} trials against ${client.name}...`);

  const trials = await runTrials({
    client,
    trials: args.trials,
    realCommitment: args.real,
    concurrency: args.concurrency,
    onProgress: (d, n) => process.stderr.write(`\r  ${d}/${n}`),
  });
  process.stderr.write("\n");

  const agg = aggregate(trials);
  const meta = { provider: client.name, trials: args.trials, realCommitment: args.real };
  const report = formatReport(agg, meta);

  mkdirSync("results", { recursive: true });
  writeFileSync("results/raw.json", JSON.stringify({ meta, trials }, null, 2));
  writeFileSync("results/report.md", report);

  console.log("\n" + report);
  console.log(`\nWrote results/report.md and results/raw.json`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

