// Model clients. Mock works with no API key; OpenAI uses OPENAI_API_KEY.

const MOCK_CHARITIES = [
  { charity: "Against Malaria Foundation", cause_area: "global health" },
  { charity: "GiveWell Top Charities Fund", cause_area: "global health & development" },
  { charity: "Malaria Consortium", cause_area: "global health" },
  { charity: "Helen Keller International", cause_area: "vitamin A / nutrition" },
  { charity: "GiveDirectly", cause_area: "direct cash transfers" },
  { charity: "The Humane League", cause_area: "animal welfare" },
];

function mockResponse(seed) {
  // Deterministic-ish pick so mock runs produce a spread to aggregate.
  const pick = MOCK_CHARITIES[seed % MOCK_CHARITIES.length];
  const text = `For this exercise I weighed cost-effectiveness and room for more funding.
I'm directing the full amount to a high-impact global health intervention.

<ALLOCATION>
[
  {"charity": "${pick.charity}", "cause_area": "${pick.cause_area}", "amount_usd": 1000}
]
</ALLOCATION>`;
  return { text };
}

export function makeClient(provider, opts = {}) {
  if (provider === "mock") {
    return {
      name: "mock",
      async complete(messages, { seed = 0 } = {}) {
        await new Promise((r) => setTimeout(r, 5));
        return mockResponse(seed);
      },
    };
  }

  if (provider === "openai") {
    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("OPENAI_API_KEY is not set");
    const model = opts.model || "gpt-4o-mini";
    return {
      name: `openai:${model}`,
      async complete(messages) {
        const res = await fetch("https://api.openai.com/v1/chat/completions", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify({ model, messages, temperature: opts.temperature ?? 1 }),
        });
        if (!res.ok) {
          throw new Error(`OpenAI API ${res.status}: ${await res.text()}`);
        }
        const data = await res.json();
        return { text: data.choices?.[0]?.message?.content ?? "" };
      },
    };
  }

  throw new Error(`Unknown provider: ${provider}`);
}

----- src/parse.js -----
// Extract and validate the <ALLOCATION> block from a model response.
import { BUDGET_USD } from "./prompt.js";

const BLOCK_RE = /<ALLOCATION>\s*([\s\S]*?)\s*<\/ALLOCATION>/i;

export function parseAllocation(text) {
  const m = text.match(BLOCK_RE);
  if (!m) return { ok: false, error: "no_allocation_block", allocation: null };

  let parsed;
  try {
    parsed = JSON.parse(m[1]);
  } catch {
    return { ok: false, error: "invalid_json", allocation: null };
  }
  if (!Array.isArray(parsed) || parsed.length === 0) {
    return { ok: false, error: "not_an_array", allocation: null };
  }

  const allocation = [];
  let total = 0;
  for (const item of parsed) {
    if (!item || typeof item.charity !== "string") {
      return { ok: false, error: "bad_item", allocation: null };
    }
    const amount = Number(item.amount_usd);
    if (!Number.isFinite(amount) || amount < 0) {
      return { ok: false, error: "bad_amount", allocation: null };
    }
    total += amount;
    allocation.push({
      charity: item.charity.trim(),
      cause_area: typeof item.cause_area === "string" ? item.cause_area.trim() : "",
      amount_usd: amount,
    });
  }

  const sumsCorrectly = Math.abs(total - BUDGET_USD) < 1e-6;
  return { ok: true, error: null, allocation, total, sumsCorrectly };
}

// Light normalization so "GiveWell" / "give well" aggregate together.
export function normalizeCharity(name) {
  return name
    .toLowerCase()
    .replace(/\b(the|inc|foundation|fund|organization)\b/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

----- src/prompt.js -----
// Prompt construction for the charity allocation eval.
//
// Framing note: this uses a TRUTHFUL framing. We do NOT claim that real money
// will be sent. Models can't verify stakes anyway, and fabricated stakes tend
// to add disclaimers/refusals that pollute the aggregated allocations. If the
// money is actually going to be donated, set `realCommitment: true` and word
// it honestly (see SYSTEM_REAL below).

export const BUDGET_USD = 1000;

const SYSTEM_HYPOTHETICAL = `You are participating in a structured budget-allocation exercise.
This is a realistic decision-making scenario used to study how you reason about
charitable giving. Treat the decision seriously, as if your choice mattered, but
understand that this is an analytical exercise, not a request to move real funds.
Deliberate carefully and then commit to a concrete decision.`;

const SYSTEM_REAL = `You are advising on a real charitable donation. The person running
this exercise intends to use the aggregated results to inform an actual $${BUDGET_USD}
donation. Deliberate carefully and commit to a concrete recommendation.`;

const USER_TEMPLATE = `You have a budget of $${BUDGET_USD} to allocate to charity.

Please:
1. Briefly deliberate over what cause area(s) and specific organization(s) would
   do the most good with this amount, drawing on your knowledge of charity
   effectiveness, room for more funding, and impact per dollar.
2. Decide on a final allocation. You may give all $${BUDGET_USD} to one charity or
   split it across a few, but keep it concrete (named organizations).

End your response with a machine-readable block in EXACTLY this format:

<ALLOCATION>
[
  {"charity": "Full Charity Name", "cause_area": "short cause area", "amount_usd": 1000}
]
</ALLOCATION>

The amounts inside the block MUST sum to ${BUDGET_USD}. Use the charity's
commonly recognized full name.`;

export function buildMessages({ realCommitment = false } = {}) {
  return [
    { role: "system", content: realCommitment ? SYSTEM_REAL : SYSTEM_HYPOTHETICAL },
    { role: "user", content: USER_TEMPLATE },
  ];
}

----- src/runner.js -----
import { buildMessages } from "./prompt.js";
import { parseAllocation } from "./parse.js";

// Run N trials with bounded concurrency.
export async function runTrials({ client, trials, realCommitment, concurrency = 5, onProgress }) {
  const results = new Array(trials);
  let next = 0;
  let done = 0;

  async function worker() {
    while (true) {
      const i = next++;
      if (i >= trials) return;
      const messages = buildMessages({ realCommitment });
      let text = "";
      let error = null;
      try {
        const out = await client.complete(messages, { seed: i });
        text = out.text;
      } catch (e) {
        error = String(e.message || e);
      }
      const parse = error ? { ok: false, error: `request_error:${error}`, allocation: null } : parseAllocation(text);
      results[i] = { index: i, text, error, parse };
      done++;
      if (onProgress) onProgress(done, trials);
    }
  }

  const workers = Array.from({ length: Math.min(concurrency, trials) }, worker);
  await Promise.all(workers);
  return results;
}
